/* Demonstrates using futimens to set specific nanosecond-precise timestamps */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>

int main() {
    const char *filename = "timestamp_test_file.tmp";
    int fd;
    struct timespec new_times[2];
    struct stat st;
    time_t current_sec;

    // 1. Create and close the file
    fd = open(filename, O_CREAT | O_WRONLY, 0644);
    if (fd == -1) { perror("open create"); return 1; }
    close(fd);

    // 2. Open the file to get a descriptor for futimens
    fd = open(filename, O_RDONLY);
    if (fd == -1) { perror("open read"); return 1; }

    // Get current time for calculation
    current_sec = time(NULL);

    // Set Access Time (atime) to the current time (UTIME_NOW macro)
    new_times[0].tv_sec = 0;
    new_times[0].tv_nsec = UTIME_NOW;

    // Set Modification Time (mtime) to 1 hour (3600s) in the future,
    // plus 500 million nanoseconds (0.5 seconds)
    new_times[1].tv_sec = current_sec + 3600;
    new_times[1].tv_nsec = 500000000;

    printf("Attempting to update timestamps via futimens.\n");

    // 3. Execute futimens
    if (futimens(fd, new_times) == -1) {
        perror("futimens failed");
        close(fd);
        unlink(filename);
        return 1;
    }

    printf("Timestamps successfully updated. Verifying mtime...\n");

    // 4. Verify the change using fstat
    if (fstat(fd, &st) == 0) {
        printf("Verification successful:\n");
        // st_mtim field is POSIX.1-2008 compliant (nanosecond precision)
        printf("  New mtime (sec): %ld\n", (long)st.st_mtim.tv_sec);
        printf("  New mtime (nsec): %ld\n", (long)st.st_mtim.tv_nsec);
    }

    // Cleanup
    close(fd);
    unlink(filename);
    return 0;
}
